def solve(transition,sensor,initial,process_noise,measurement_noise):
    states=[initial[:]]
    for noise in process_noise:
        states.append([sum(a*b for a,b in zip(row,states[-1]))+value for row,value in zip(transition,noise)])
    return states,[sum(a*b for a,b in zip(sensor,state))+noise for state,noise in zip(states,measurement_noise)]

