import math
def solve(truth,means,standard_deviations,z):
    n=len(truth);rmse=math.sqrt(sum((x-m)**2 for x,m in zip(truth,means))/n)
    coverage=sum(abs(x-m)<=z*s for x,m,s in zip(truth,means,standard_deviations))/n
    return rmse,coverage,math.sqrt(coverage*(1-coverage)/n)

