import math
def solve(samples,log_target,log_proposal):
    scores=[a-b for a,b in zip(log_target,log_proposal)];peak=max(scores);mass=[math.exp(x-peak) for x in scores];total=sum(mass);weights=[x/total for x in mass]
    return weights,sum(w*x for w,x in zip(weights,samples)),1/sum(w*w for w in weights)

p07-hmm-smoothing:
def solve(initial,transition,likelihoods):
    n=len(initial);alpha=[];current=initial[:]
    for t,likelihood in enumerate(likelihoods):
        prediction=current[:] if t==0 else [sum(current[i]*transition[i][j] for i in range(n)) for j in range(n)]
        emission=[1.]*n if likelihood is None else likelihood
        mass=[a*b for a,b in zip(prediction,emission)];current=[x/sum(mass) for x in mass];alpha.append(current)
    beta=[1.]*n;result=[None]*len(alpha)
    for t in range(len(alpha)-1,-1,-1):
        mass=[a*b for a,b in zip(alpha[t],beta)];result[t]=[x/sum(mass) for x in mass]
        if t>0:
            emission=[1.]*n if likelihoods[t] is None else likelihoods[t]
            beta=[sum(transition[i][j]*emission[j]*beta[j] for j in range(n)) for i in range(n)];scale=sum(beta);beta=[x/scale for x in beta]
    return result
